def management_role_to_team(apps, schema_editor):
    """역할 '경영지원팀'(management)이던 계정 → 역할 팀장 + 경영지원팀 소속(열람·수정).

    옛 역할에는 팀장·팀원 구분이 없었으므로 모두 팀장으로 옮긴다(권한은 둘 다 전체라 차이 없음).
    팀원으로 바꿀 계정은 관리자 설정 화면에서 바꾼다.
    """
    User = apps.get_model("accounts", "User")
    for user in User.objects.filter(role="management"):
        user.role = "leader"
        user.view_teams = ["management"] + [t for t in user.view_teams if t != "management"]
        user.edit_teams = ["management"] + [t for t in user.edit_teams if t != "management"]
        user.save(update_fields=["role", "view_teams", "edit_teams"])


def team_to_management_role(apps, schema_editor):
    """되돌리기: 경영지원팀 소속인 팀장·팀원 → 역할 '경영지원팀'"""
    User = apps.get_model("accounts", "User")
    for user in User.objects.filter(role__in=["leader", "member"], view_teams__contains=["management"]):
        user.role = "management"
        user.view_teams = [t for t in user.view_teams if t != "management"]
        user.edit_teams = [t for t in user.edit_teams if t != "management"]
        user.save(update_fields=["role", "view_teams", "edit_teams"])


